package caddy

import "testing"

func TestEscapeCloseBraceRepro(t *testing.T) {
	r := NewReplacer()
	if got := r.ReplaceAll(`\}`, ""); got != `}` {
		t.Fatalf("got %q", got)
	}
	if got := r.ReplaceAll(`\{`, ""); got != `{` {
		t.Fatalf("got %q", got)
	}
	if got := r.ReplaceAll(`a\}b\{c`, ""); got != `a}b{c` {
		t.Fatalf("got %q", got)
	}
	// plain backslashes and unknown escapes must be preserved
	if got := r.ReplaceAll(`C:\path\to`, ""); got != `C:\path\to` {
		t.Fatalf("got %q", got)
	}
	// placeholders still work
	r.Set("foo", "bar")
	if got := r.ReplaceAll(`{foo}\}`, ""); got != `bar}` {
		t.Fatalf("got %q", got)
	}
}
EOF
