package rewrite

import (
	"net/http"
	"net/url"
	"testing"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/caddyfile"
)

func TestUriReplaceEscapedBraces(t *testing.T) {
	input := []byte(`:80
uri replace "\}" %7D
uri replace "\{" %7B
`)
	tokens, err := caddyfile.Tokenize(input, "Caddyfile")
	if err != nil {
		t.Fatal(err)
	}
	// use the caddyfile parse to handler path via httpcaddyfile would need full setup;
	// instead mimic what the dispenser gives the directive parser
	d := caddyfile.NewDispenser(tokens)
	d.Next() // :80
	d.Next() // uri
	h := setupHelper(d)
	handler, err := parseCaddyfileURI(h)
	if err != nil {
		t.Fatal(err)
	}
	rewr := handler.(*Rewrite)
	if len(rewr.URISubstring) != 2 {
		t.Fatalf("expected 2 replacers, got %d: %+v", len(rewr.URISubstring), rewr.URISubstring)
	}
	if rewr.URISubstring[0].Find != "}" || rewr.URISubstring[1].Find != "{" {
		t.Fatalf("unexpected find values: %+v", rewr.URISubstring)
	}

	req := &http.Request{URL: &url.URL{Path: "/endpoint", RawQuery: "test={%20content%20}"}}
	req.RequestURI = "/endpoint?test={%20content%20}"
	repl := caddy.NewReplacer()
	rewr.Rewrite(req, repl)
	if req.URL.RawQuery != "test=%7B%20content%20%7D" {
		t.Fatalf("query not fully replaced: %q", req.URL.RawQuery)
	}
}
EOF
